#!/usr/bin/env bash
# run2.sh <run> : Octo-ooze art trial v2, portrait style. Needs $R/reference/{frames,portrait}.png
T='D:/Coding/BYMR/art-trials/octo-ooze/kit'
R="$T/$1"
date +%T
bash ~/.claude/scripts/agy-delegate.sh --write --yolo --timeout 10m --dir "$R" -- "You are repainting tiny game sprites. Workspace folder: $R. reference/portrait.png is the OFFICIAL concept painting of the monster (the Octo-ooze): a glossy teal-blue slimy blob body with a jagged toothy mouth full of small white fangs along the top rim of the body, a tall thick wobbly neck/stalk rising from the body topped with two big bulging orange-red slit-pupil eyeballs, and six thick curling grey-tan tentacle legs with pale suction undersides spread around the base. reference/frames.png is a 2x2 grid (cells 320x256 px, grey ground) of 4 low-resolution isometric game sprite frames of the same monster blown up 8x (old design, blurry, green with little spiky legs): top-left facing right/east, top-right facing down/south toward the viewer, bottom-left facing left/west, bottom-right facing up/north showing its back. TASK: generate ONE new image saved as out/frames-new.png with exactly the same 2x2 grid layout and canvas proportions as reference/frames.png (640x512 or a 2x multiple); each monster at the same position, same overall size, same pose and same facing as the matching reference cell, BUT redesigned to look exactly like the monster in portrait.png (use the portrait for design, colours, anatomy and painting style; use frames.png only for facing, position and size, ignore its green colours and spiky legs; keep the eye stalk fairly short so the whole monster stays about as big as in the reference). Style: the same hand-painted digital illustration look as the portrait: soft shading, rich texture, glossy wet highlights on eyes and body, NO thick cartoon outline, NOT cute, no cel shading, no pixel art. Seen from the isometric 3/4 game camera at each facing (south: face and eyes toward viewer; north: show the back of the blob and the back of the eye stalk, no fangs). Keep the design identical in all 4 cells. Each cell: the monster on its own soft shadow is NOT needed - draw NO shadow. Background everywhere in the whole image must be flat pure magenta #FF00FF, no grid lines, no text, no labels, no shadows. IMPORTANT: do NOT write or run any code or scripts, and do NOT warp, cut, copy or composite pixels from any reference image - the new image must be produced by ONE call to your image generation tool, passing both reference images as inputs. Then save it as out/frames-new.png. Reply DONE when the file exists." 2>&1 | tail -4
date +%T; ls -la "$R/out"
